param(
    [string]$Repo = ".",
    [switch]$RunTests
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version 2.0

function Fail([string]$Message) {
    throw "SplitWire DNS hotfix: $Message"
}

function Get-Sha256([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return "" }
    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
}

$RepoPath = (Resolve-Path -LiteralPath $Repo).Path
if (-not (Test-Path -LiteralPath (Join-Path $RepoPath "go.mod") -PathType Leaf)) {
    Fail "'$RepoPath' does not look like the SplitWire repository root (go.mod not found)."
}

$Files = @(

    @{ Path = "internal/engine/proxydial.go"; Before = "5d1fe1cf8a62518404b291fb793f203146eeda719a79e6bd6c6aa28d4cda0066"; After = "6e9acfccabb69b372ff02cc67e515368526385f9e429786c91299e90b9143958"; Data = "" },
    @{ Path = "internal/engine/proxydial_test.go"; Before = "036f69a1bd8f11e9a6cfe4ab2bf462f7de76eec4beacd1ca4ec8f0be01b79bc2"; After = "9f61940ce6a53ff0f776de42a39bce5f7c5d235316e3b5f0e1dd722f72da8349"; Data = "" },
    @{ Path = "internal/engine/proxy_windows.go"; Before = "f9ed81c636d5159eef28e4e75c1e9b5156d7478481ab2d621a47de350249e553"; After = "ef7035fcea05ea5edfa7a2c16ffca3e0ee2c7f8e9b29f6a713fd2501f09a2ec5"; Data = "" },
    @{ Path = "internal/engine/engine_windows.go"; Before = "6b35d76a3ae6134406c1d9e8e74c547b06a335f89969d674290a254a3cf71062"; After = "97759c9598806692f1810f902dfd805103468d00b939234636c0d67057863673"; Data = "" },
    @{ Path = "cmd/splitwire/main_windows.go"; Before = "065a547daf65622f01c12829564a8cb8e4b4c087865a8dee342ddc9c25656639"; After = "319fabd36e47a5aacdf76836d6fc7ea2fd6cc3bfb5f0dfbf6e6ef55d74b086db"; Data = "" },
    @{ Path = "CHANGELOG_1.2.2_DNSFIX1.md"; Before = $null; After = "00704d9db81862d97f26c158e3ae67f9371a3ca57378cf00748422ecff573bb9"; Data = "" }
)

$already = $true
foreach ($item in $Files) {
    $target = Join-Path $RepoPath ($item.Path -replace '/', [IO.Path]::DirectorySeparatorChar)
    if ((Get-Sha256 $target) -ne $item.After) { $already = $false; break }
}
if ($already) {
    Write-Host "SplitWire 1.2.2-dnsfix1 is already applied."
    exit 0
}

foreach ($item in $Files) {
    $target = Join-Path $RepoPath ($item.Path -replace '/', [IO.Path]::DirectorySeparatorChar)
    $cur = Get-Sha256 $target
    if ($item.Before) {
        if ($cur -ne $item.Before -and $cur -ne $item.After) {
            Fail "unexpected base file: $($item.Path)`nexpected 1.2.2: $($item.Before)`nfound:          $cur`nApply the full 1.2.2 patch first, or restore this file before using the incremental DNS hotfix."
        }
    } else {
        if ($cur -and $cur -ne $item.After) {
            Fail "new hotfix file already exists with unexpected content: $($item.Path)"
        }
    }
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = Join-Path $env:TEMP "SplitWire-1.2.2-dnsfix1-backup-$stamp"
New-Item -ItemType Directory -Path $backup -Force | Out-Null

try {
    foreach ($item in $Files) {
        $rel = $item.Path -replace '/', [IO.Path]::DirectorySeparatorChar
        $target = Join-Path $RepoPath $rel
        if (Test-Path -LiteralPath $target -PathType Leaf) {
            $backupFile = Join-Path $backup $rel
            New-Item -ItemType Directory -Path (Split-Path -Parent $backupFile) -Force | Out-Null
            Copy-Item -LiteralPath $target -Destination $backupFile -Force
        }

        New-Item -ItemType Directory -Path (Split-Path -Parent $target) -Force | Out-Null
        $bytes = [Convert]::FromBase64String($item.Data)
        [IO.File]::WriteAllBytes($target, $bytes)
        $actual = Get-Sha256 $target
        if ($actual -ne $item.After) {
            Fail "verification failed for $($item.Path): expected $($item.After), got $actual"
        }
        Write-Host "patched $($item.Path)"
    }

    Push-Location $RepoPath
    try {
        & git diff --check
        if ($LASTEXITCODE -ne 0) { Fail "git diff --check failed" }

        if ($RunTests) {
            & go test -count=1 ./...
            if ($LASTEXITCODE -ne 0) { Fail "go test failed" }
            & go vet ./...
            if ($LASTEXITCODE -ne 0) { Fail "go vet failed" }

            $oldGOOS = $env:GOOS; $oldGOARCH = $env:GOARCH; $oldCGO = $env:CGO_ENABLED
            try {
                $env:GOOS = "windows"; $env:GOARCH = "amd64"; $env:CGO_ENABLED = "0"
                & go vet ./...
                if ($LASTEXITCODE -ne 0) { Fail "Windows cross-vet failed" }
                $tmpExe = Join-Path $env:TEMP "SplitWire-dnsfix1-test.exe"
                & go build -buildvcs=false -trimpath -ldflags=-H=windowsgui -o $tmpExe ./cmd/splitwire
                if ($LASTEXITCODE -ne 0) { Fail "Windows GUI cross-build failed" }
                Remove-Item -LiteralPath $tmpExe -Force -ErrorAction SilentlyContinue
            } finally {
                $env:GOOS = $oldGOOS; $env:GOARCH = $oldGOARCH; $env:CGO_ENABLED = $oldCGO
            }
        }
    } finally {
        Pop-Location
    }
} catch {
    Write-Warning "Hotfix failed. Backup is at: $backup"
    throw
}

Write-Host ""
Write-Host "SplitWire 1.2.2-dnsfix1 applied successfully."
Write-Host "Backup: $backup"
Write-Host "Restart SplitWire completely before testing ChatGPT/YouTube."
Write-Host "Expected startup log contains: registered UDP/TCP sockets; system DNS fallback enabled"
